style.css:
@-moz-document domain("wiki.musicbrainz.org") {
/* Reclaim the left half of the screen */
	#content {
		margin-left: unset !important;
	}
	/* Show Page Actions popup menu */
	#p-cactions {
		z-index: 10000;
	}
	#p-cactions li a:hover {
		color: black;
	}
	/* Show Discussion and Edit Source menu items */
	#ca-edit, #ca-talk {
		position: initial !important;
	}
}
